values
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-01', 'cruce roșie', array[]::text[], '**\+ Нова година. Обрезание Господне.** Св. Василий Велики. Св. Емилия. Св. мчк Василий Анкирски (*Вас. лит.*) (*Василовден*) (Тип. с. 164)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-02', null, array[]::text[], 'Св. Силвестър, папа Римски. Преп. Серафим Саровски Чудотворец (*Предпразненство на св. Богоявление*) (*Блажи се*)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-03', null, array[]::text[], 'Св. прор. Малахия. Св. мчк Гордий', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-04', 'cruce roșie', array[]::text[], '**\+ Неделя преди Богоявление.** Събор на св. 70 апостоли. Прпмчк Онуфрий Габровски. Преп. Теоктист. Гл. 5, утр. ев. 8, ап. 2 Тим 4: 5-8 (с. 448), лит. ев. Мк 1:1-8 (с. 302) \[прпмчк Онуфрий Габровски: 2 Тим. 1: 8-18 (с. 355), лит. ев. Мк 8: 34-38, 9: 1)\] (Тип. с. 169)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-05', null, array[]::text[], 'Св. прор. Михей. Св. мчци Теопемт и Теона. Преп. Синклитикия и Аполинария ***(Водици) (Утреня, Царски часове, Вечерня с Вас. лит.) (Велик водосвет) (Строг пост)*** (Тип. с. 172)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-06', 'cruce roșie', array[]::text[], '**\+ Св. Богоявление** *(Утреня, Злат. лит.) (Велик водосвет) (Йордановден)* (Тип. с. 174)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-07', 'cruce roșie', array[]::text[], '**\+ Св. Йоан Кръстител** *(Ивановден)* (Тип. с. 177)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-08', null, array[]::text[], 'Св. Григорий, еп. Български. Преп. Георги Хозевит. Св. Емилиан изповедник. Преп. Домника. Мчк Або Тбилиски', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-09', null, array[]::text[], 'Св. мчк Полиевкт. Св. Петър, еп. Севастийски. Преп. Евстратий', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-10', null, array[]::text[], 'Св. Григорий, еп. Нисийски. Преп. Дометиан, еп. Мелитински. Св. Маркиан. Св. Теофан Затворник. Блажена Теозви', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-11', 'cruce roșie', array[]::text[], '**\+ Неделя след Богоявление.** Преп. Теодосий Велики. Преп. Теодосий Антиохийски. Гл. 6, утр. ев. 9, ап. Ефес. 4:7-13 (457) лит. ев. Мт 4:12-17 (с. 308) \[на преподобния ап. Евр. 13:7-16 (с. 458), лит. ев. Мт 11: 27-30 (с. 309)\] (Тип. с. 180)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-12', null, array[]::text[], 'Св. мчца Татяна Римска. Св. Сава Сръбски. Св. мчк Мертий. Мчк Петър Авесаломит. Преп. Евпраксия', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-13', null, array[]::text[], 'Св. мчци Ермил и Стратоник. Св. мчк Петър Анийски. Преп. Максим Кавсокаливит. Св. Йеремия I, патр. Константинополски', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-14', null, array[]::text[], 'Преп. отци, избити в Синай и Раита. Св. равноап. Нина. Св. Потит Сердикийски *(Отдание на Богоявление)* (Тип. с. 181)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-15', null, array[]::text[], 'Преп. отци Гавриил Лесновски, Прохор Пшински, Павел Тивейски и Йоан Колибар. Св. Герасим, патр. Александрийски', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-16', null, array[]::text[], 'Честни вериги на св. ап. Петър. Преп. Ромил Видински. Св. свщмчк Дамаскин Габровски', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-17', null, array[]::text[], '**\* Преп. Антоний Велики** (Тип. с. 184) *(Антоновден)*', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-18', 'cruce roșie', array[]::text[], '**\+ Неделя 12 след Неделя подир Въздвижение - на 10-те прокажени. Св. Атанасий и Кирил Александрийски.** Св. Йоаким, патр. Търновски *(Атанасовден)*. Гл. 7, утр. ев. 10, ап. Кол. 3: 4-11, лит. ев. Лк 17:12-19(с. 145), \[на светителите: ап. Евр. 13:7-16 (с. 462), лит. ев. Мт 5: 14-19 (с. 311)\], \[на св. Йоаким Търновски: ап. ЕВр. 7: 26-28, 8: 1-2(с. 350), лит. ев. Ин 10: 9-16 (с. 235)\] (Тип. с. 188).', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-19', null, array[]::text[], 'Преп. Макарий Египетски. Св. Марк, еп. Ефески', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-20', null, array[]::text[], '**\* Преп. Евтимий Велики. Св. Евтимий, патриарх Търновски** (Тип. с. 191)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-21', null, array[]::text[], 'Преп. Максим Изповедник. Св. мчк Неофит', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-22', null, array[]::text[], 'Св. ап. Тимотей. Прпмчк Анастасий Перски. Св. свщмчк Петър, еп. Български. Св. мчк Сионий Български', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-23', null, array[]::text[], 'Св. свщмчк Климент, еп. Анкирски. Св. мчк Агатангел. Св. Павлин, еп. Нолански', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-24', null, array[]::text[], 'Преп. Ксения Римлянка. Блаж. Ксения Петербургска. Преп. Филон, еп. Колпастийски', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-25', 'cruce roșie', array[]::text[], '**\+ Неделя 15 след Неделя подир Въздвижение ¬ на Закхея. Св. Григорий Богослов, архиепископ Константинополски.** Гл. 8, утр. ев. 11, ап. 1 Тим 4: 9-15 (с. 291,) лит. ев. Лк 19:1-10 (с. 155) \[на светителя: ап. Евр. 7:26-28, 8:1-2 (с. 466), лит. ев. Ин 10: 9-16 (с. 313)\] (Тип. с. 194)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-26', null, array[]::text[], 'Преп. Ксенофонт и дружината му. Св. Амон. Св. Павла', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-27', null, array[]::text[], '**\* Пренасяне мощите на св. Йоан Златоуст** (Тип. с. 196)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-28', null, array[]::text[], 'Преп. Ефрем Сириец. Св. Исаак Сириец, епископ Ниневийски. Преп. Паладий Пустинник', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-29', null, array[]::text[], 'Пренасяне мощите на св. Игнатий Богоносец. Св. мчк Димитрий Сливенски. Св. Димитрий Гагастатис, презвитер', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-30', null, array[]::text[], '**\* Св. Трисветители велики архиереи: Василий Велики, Григорий Богослов и Йоан Златоуст.** Св. свщмчк Иполит, папа Римски. Св. благоверен цар Петър Български. Преп. Сергий Къпински (Тип. с. 200)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-01-31', null, array[]::text[], 'Св. безсребреници и чудотворци Кир и Йоан. Св. Серапион и Папий', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-02-01', 'cruce roșie', array[]::text[], '**\+ Неделя 16 след Неделя подир Въздвижение - на Митаря и Фарисея. Св. мчк Трифон** *(Предпразненство на Сретение Господне) (Трифоновден)*. Гл. 1, утр. ев. 1, ап. 2 Тим 3:10-15 (с. 299), лит. ев. Лк 18:10-14 (с. 158) \[на св. мчк Трифон: ап. Рим. 8:28-39 (с. 469), лит. ев. Лк 10: 16-21 (с. 315)\] (Тип. с. 207, т. 3)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-02-02', 'cruce roșie', array[]::text[], '**\+ Сретение Господне** (Тип. с. 208)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-02-03', null, array[]::text[], 'Св. Симеон Богоприимец и Анна пророчица. Св. пророк Азарий. Св. равноап Николай Японски', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-02-04', null, array[]::text[], 'Преп. Исидор Пелусийски. Св. мчк Иадор. Преп. Иасим Чудотворец *(Блажи се)* (Тип. с. 415, заб.)', null, 'Блажи се', 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-02-05', null, array[]::text[], 'Св. мчца Агатия (Добра). Св. мчца Василиса', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-02-06', null, array[]::text[], 'Преп. Вукол, еп. Смирненски. Св. Фотий, патр. Константинополски. Преп. Варсануфий Велики. Св. Йоан Пророк. Св. мчци Доротея, Христина и Калиста *(Блажи се)*', null, 'Блажи се', 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-02-07', null, array[]::text[], 'Преп. Партений, еп. Лампсакийски. Преп. Лука Еладски. Преп. Априон, еп. Кипърски', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-02-08', 'cruce roșie', array[]::text[], '**\+ Неделя 17 след Неделя подир Въздвижение ¬ на Блудния син.** Св. вмчк Теодор Стратилат. Св. прор. Захария Сърповидец. Гл. 2, утр. ев. 2, ап. 1 Кор. 6:12-20 (с. 308), лит. ев. Лк 15:11-32 (с. 161 ) (Тип. с. 416)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-02-09', null, array[]::text[], 'Св. мчк Никифор *(Отдание на Сретение Господне)* (Тип. с. 216, т. 1)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-02-10', null, array[]::text[], '**\* Св. свщмчк Харалампий Чудотворец.** Св. мчца Валентина (Тип. 219)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-02-11', null, array[]::text[], '\* Св. свщмчк Власий, еп. Севастийски. Св. мчк Георги Софийски, Нови', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-02-12', null, array[]::text[], 'Св. Мелетий, архиеп. Антиохийски. Св. Антоний, патр. Константинополски', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-02-13', null, array[]::text[], 'Преп. Мартиниан. Св. Евлогий, архиеп. Александрийски. Преп. Зоя (Живка) и Фотина (Светлана)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-02-14', null, array[]::text[], '**\* Успение на св. Кирил Славянобългарски** (Тип. с. 225, виж с. 228, т.3). Преп. Авксентий. ***(Задушница)*** (Тип. с. 417)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
