  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-06-22', null, array[]::text[], 'Св. свщмчк Евсевий, еп. Самосатски. Св. мчци Зинон и Зина. Св. мчци Галактион и Юлиания', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-06-23', null, array[]::text[], 'Св. мчца Агрипина. Св. преп. Антоний и Йоаникий', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-06-24', null, array[]::text[], '**\*Рождение на св. Йоан Кръстител** *(Еньовден)*. Св. Никита, еп. Ремесиански (Тип. с. 342, т. 7)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
