  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-07-15', null, array[]::text[], '\*Св. мчци Кирик и Юлита. Св. равноап. велик княз Владимир (Тип. с. 372, т. 1 или с. 373, т. 3)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-07-16', null, array[]::text[], 'Св. свщмчк Атиноген, еп. Севастийски и 10-те му ученици. Св. мчца Юлия девица. Св. мчк Йоан Търновски. Събор на св. свщмчци Николаос Хеше и синът му Хабиб', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
