  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-07-29', null, array[]::text[], '\*Св. свщмчк Висарион Смоленски. Св. мчк Калиник. Св. мчца Серафима девица', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-07-30', null, array[]::text[], 'Св. апли от 70-те Сила, Силуан, Крискент, Епенет и Андроник. Св. Валентин, еп. Интерамски *(Богородични заговезни)*', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-07-31', null, array[]::text[], 'Св. праведен Евдоким Кападокийски. Св. мчца Юлита и св. Йосиф Ариматейски', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-08-01', null, array[]::text[], '**\*Произхождение (изнасяне) на св. Кръст.** Св. мчци 7 братя Макавеи. Св. Соломония. Св. Елеазар. *(Водосвет) (Начало на Богородичния пост)* (Тип. с. 383)', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
