  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-08-03', null, array[]::text[], 'Преп. Исакий, Фавст и Далмат *(вечерта - Вечерня с Молебен канон на Пресвета Богородица)*', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-08-04', null, array[]::text[], 'Св. 7 отроци в Ефес. Св. прпмчца Евдокия *(вечерта - Вечерня с Молебен канон на Пресвета Богородица)*', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
  ('BG', 'bg', 'bg-bulgarian-patriarchate', '2026-08-05', null, array[]::text[], 'Св. мчк Евсигний *(Предпр. на Преображение Господне)*', null, null, 'Българска Православна Църква – Българска Патриаршия, Православен календар 2026 (https://bg-patriarshia.bg/calendar/2026)', true),
